+  --shadow: 0 18px 60px rgba(0,0,0,.55);
+
+  --red: #E63946;
+  --red-2: #FF0000;
+  --red-glow: 0 0 0.5rem rgba(230,57,70,.35), 0 0 2.25rem rgba(230,57,70,.20);
+
+  --radius: 18px;
+  --radius-sm: 12px;
+
+  --container: 1160px;
+  --gutter: 20px;
+
+  --font-display: "Bebas Neue", system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
+  --font-sans: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family:var(--font-sans);
+  background:
+    radial-gradient(1200px 800px at 15% -10%, rgba(230,57,70,.18), transparent 55%),
