+    radial-gradient(900px 700px at 40% 120%, rgba(230,57,70,.10), transparent 60%),
+    linear-gradient(180deg, #0b0b0c, var(--bg) 40%, #0b0b0c);
+  color:var(--text);
+  line-height:1.55;
+}
+img{max-width:100%;display:block}
+a{color:inherit;text-decoration:none}
+
+.skip-link{
+  position:absolute;
+  top:8px;
+  left:8px;
+  background:#000;
+  border:1px solid var(--border);
+  padding:10px 12px;
+  border-radius:10px;
+  transform:translateY(-140%);
+  transition:transform 180ms ease;
+  z-index:9999;
+}
+.skip-link:focus{transform:translateY(0)}
+
+.container{max-width:var(--container);margin:0 auto;padding:0 var(--gutter)}
+
+.topbar{
+  background:linear-gradient(90deg, rgba(230,57,70,.25), rgba(255,0,0,.08));
