+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  border-radius:999px;
+  border:1px solid transparent;
+  padding:12px 16px;
+  font-weight:650;
+  letter-spacing:.02em;
+  cursor:pointer;
+  transition:transform 140ms ease, background 180ms ease, border-color 180ms ease, box-shadow 180ms ease, opacity 180ms ease;
+  user-select:none;
+}
+.btn:focus-visible{outline:3px solid rgba(230,57,70,.55);outline-offset:2px}
+.btn--sm{padding:10px 14px;font-size:13px}
+.btn--lg{padding:14px 20px;font-size:15px}
+.btn--primary{background:linear-gradient(180deg, var(--red), #b41622);box-shadow:var(--red-glow)}
+.btn--primary:hover{transform:translateY(-1px);box-shadow:0 0 0.6rem rgba(230,57,70,.42), 0 0 2.6rem rgba(230,57,70,.24)}
+.btn--primary:active{transform:translateY(0)}
+.btn--secondary{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.14)}
+.btn--secondary:hover{background:rgba(255,255,255,.12);transform:translateY(-1px)}
+.btn--ghost{background:transparent;border-color:rgba(255,255,255,.18)}
+.btn--ghost:hover{background:rgba(255,255,255,.06)}
+
+.header{
+  position:sticky;
+  top:0;
+  z-index:50;
+  backdrop-filter:blur(12px);
+  background:rgba(10,10,11,.62);
+  border-bottom:1px solid rgba(255,255,255,.08);
+}
+.header__inner{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 0}
+.brand{display:flex;align-items:center;gap:12px;min-width:max-content}
+.brand__mark{
+  width:40px;height:40px;border-radius:12px;
+  background:radial-gradient(circle at 30% 30%, rgba(255,255,255,.25), transparent 55%),
+             linear-gradient(180deg, var(--red), #7d0d14);
+  box-shadow:var(--red-glow);
+  position:relative;
+}
+.brand__mark::after{content:"";position:absolute;inset:10px;border:1px solid rgba(255,255,255,.26);border-radius:10px;transform:rotate(10deg)}
+.brand__name{font-family:var(--font-display);letter-spacing:.08em;text-transform:uppercase;font-size:22px;line-height:1}
+.brand__tag{font-size:12px;color:var(--muted);margin-top:2px}
+
+.nav{display:flex;align-items:center;gap:18px}
+.nav a{
+  font-size:13px;
+  color:rgba(255,255,255,.76);
+  padding:10px 10px;
+  border-radius:999px;
+  border:1px solid transparent;
+  transition:background 160ms ease, color 160ms ease, border-color 160ms ease;
+}
+.nav a:hover{background:rgba(255,255,255,.06);color:rgba(255,255,255,.92)}
+.nav a[aria-current="page"]{border-color:rgba(230,57,70,.55);background:rgba(230,57,70,.10);color:#fff}
+.nav__utility{display:flex;align-items:center;gap:10px}
+
+.burger{
+  display:none;
+  background:rgba(255,255,255,.06);
+  border:1px solid rgba(255,255,255,.14);
+  border-radius:12px;
+  padding:10px;
+}
+.burger svg{width:20px;height:20px}
+
+.mobile-sheet{display:none}
+.mobile-sheet[aria-hidden="false"]{display:block}
+.mobile-sheet__panel{
+  margin:12px 0 16px;
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(255,255,255,.07), rgba(255,255,255,.03));
+  border-radius:var(--radius);
+  padding:14px;
+}
+.mobile-links{display:grid;grid-template-columns:1fr;gap:8px}
+.mobile-links a{
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.04);
+}
+
+.section{padding:64px 0}
+.section--tight{padding:44px 0}
+.kicker{display:inline-flex;align-items:center;gap:10px;color:rgba(255,255,255,.85);font-weight:700;letter-spacing:.14em;text-transform:uppercase;font-size:12px}
+.kicker::before{content:"";width:14px;height:2px;background:linear-gradient(90deg, var(--red), transparent)}
+
+.h1{font-family:var(--font-display);letter-spacing:.08em;text-transform:uppercase;font-size:58px;line-height:.95;margin:14px 0 14px}
+.h2{font-family:var(--font-display);letter-spacing:.08em;text-transform:uppercase;font-size:40px;line-height:1.02;margin:0 0 12px}
+.h3{font-family:var(--font-display);letter-spacing:.08em;text-transform:uppercase;font-size:26px;line-height:1.08;margin:0 0 8px}
+.lead{font-size:18px;color:rgba(255,255,255,.78);max-width:70ch}
+.muted{color:var(--muted)}
+
+.hero{
+  padding:38px 0 20px;
+}
+.hero__grid{display:grid;grid-template-columns:1.1fr .9fr;gap:28px;align-items:stretch}
+.hero__panel{
+  border-radius:calc(var(--radius) + 6px);
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(255,255,255,.07), rgba(255,255,255,.02));
+  box-shadow:var(--shadow);
+  overflow:hidden;
+}
+.hero__panel-inner{padding:34px}
+.hero__actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:18px}
+.hero__badges{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}
+.badge{display:inline-flex;align-items:center;gap:8px;padding:10px 12px;border-radius:999px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.04);font-size:13px;color:rgba(255,255,255,.78)}
+.badge svg{width:16px;height:16px}
+
+.hero__media{
+  position:relative;
+  border-radius:calc(var(--radius) + 6px);
+  border:1px solid rgba(255,255,255,.12);
+  overflow:hidden;
+  box-shadow:var(--shadow);
+  min-height:360px;
+}
+.hero__media::before{
+  content:"";
+  position:absolute;
+  inset:0;
+  background:
+    linear-gradient(180deg, rgba(0,0,0,.15), rgba(0,0,0,.65)),
+    radial-gradient(800px 400px at 40% 20%, rgba(230,57,70,.35), transparent 60%);
+  z-index:1;
+}
+.hero__media img{width:100%;height:100%;object-fit:cover;filter:saturate(1.05) contrast(1.02)}
+.hero__media-content{position:absolute;left:18px;right:18px;bottom:18px;z-index:2}
+.hero__statgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:10px}
+.stat{padding:12px;border-radius:16px;background:rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.12)}
+.stat__num{font-family:var(--font-display);letter-spacing:.08em;text-transform:uppercase;font-size:22px;line-height:1}
+.stat__label{font-size:12px;color:rgba(255,255,255,.72);margin-top:4px}
+
+.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}
+.card{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.03));
+  padding:22px;
+}
+.card--hover{transition:transform 180ms ease, border-color 180ms ease, background 180ms ease}
+.card--hover:hover{transform:translateY(-2px);border-color:rgba(230,57,70,.38);background:linear-gradient(180deg, rgba(230,57,70,.10), rgba(255,255,255,.03))}
+.card__meta{display:flex;align-items:center;justify-content:space-between;gap:12px;color:rgba(255,255,255,.65);font-size:13px;margin-top:10px}
+
+.full-bleed{
+  border-top:1px solid rgba(255,255,255,.08);
+  border-bottom:1px solid rgba(255,255,255,.08);
+  background:radial-gradient(1000px 600px at 20% 0%, rgba(230,57,70,.16), transparent 60%), rgba(255,255,255,.02);
+}
+
+.cta-band{
+  border-radius:calc(var(--radius) + 6px);
+  border:1px solid rgba(230,57,70,.38);
+  background:
+    radial-gradient(800px 400px at 15% 0%, rgba(230,57,70,.30), transparent 55%),
+    linear-gradient(180deg, rgba(255,0,0,.12), rgba(255,255,255,.03));
+  box-shadow:var(--red-glow);
+  padding:26px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:16px;
+  overflow:hidden;
+}
+.cta-band__copy{max-width:70ch}
+.cta-band__title{font-family:var(--font-display);letter-spacing:.08em;text-transform:uppercase;font-size:34px;line-height:1;margin:0 0 8px}
+.cta-band__desc{margin:0;color:rgba(255,255,255,.76)}
+
+.carousel{position:relative}
+.carousel__viewport{overflow:hidden;border-radius:calc(var(--radius) + 6px);border:1px solid rgba(255,255,255,.12);box-shadow:var(--shadow)}
+.carousel__track{display:flex;transition:transform 520ms cubic-bezier(.2,.8,.2,1);touch-action:pan-y}
+.carousel__slide{min-width:100%;position:relative}
+.carousel__slide img{width:100%;height:440px;object-fit:cover}
+.carousel__overlay{position:absolute;inset:0;background:linear-gradient(180deg, rgba(0,0,0,.15), rgba(0,0,0,.68));display:flex;align-items:flex-end;padding:18px}
+.carousel__caption{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%}
+.carousel__caption h3{margin:0;font-family:var(--font-display);letter-spacing:.08em;text-transform:uppercase;font-size:26px}
+.carousel__caption p{margin:0;color:rgba(255,255,255,.72);font-size:13px}
+.carousel__controls{position:absolute;inset:0;pointer-events:none}
+.carousel__btn{
+  pointer-events:auto;
+  position:absolute;top:50%;transform:translateY(-50%);
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.16);
+  background:rgba(0,0,0,.38);
+  backdrop-filter:blur(10px);
+  width:44px;height:44px;
+  display:grid;place-items:center;
+  transition:transform 180ms ease, background 180ms ease, border-color 180ms ease;
+}
+.carousel__btn:hover{transform:translateY(-50%) scale(1.04);background:rgba(0,0,0,.50);border-color:rgba(230,57,70,.42)}
+.carousel__btn svg{width:20px;height:20px}
+.carousel__btn--prev{left:12px}
+.carousel__btn--next{right:12px}
+.dots{display:flex;gap:8px;justify-content:center;margin-top:14px}
+.dot{width:9px;height:9px;border-radius:999px;border:1px solid rgba(255,255,255,.22);background:rgba(255,255,255,.08);cursor:pointer;transition:transform 160ms ease, background 160ms ease, border-color 160ms ease}
+.dot[aria-current="true"]{background:rgba(230,57,70,.85);border-color:rgba(230,57,70,.85);transform:scale(1.1)}
+
+.form{
+  display:grid;
+  grid-template-columns:1.2fr auto;
+  gap:12px;
+  align-items:start;
+}
+.field{display:grid;gap:8px}
+.label{font-size:13px;color:rgba(255,255,255,.74)}
+.input{
+  width:100%;
+  background:rgba(255,255,255,.04);
+  border:1px solid rgba(255,255,255,.14);
+  border-radius:14px;
+  padding:12px 14px;
+  color:#fff;
+  outline:none;
+  transition:border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
+}
+.input:focus{border-color:rgba(230,57,70,.55);box-shadow:0 0 0 4px rgba(230,57,70,.18);background:rgba(255,255,255,.06)}
+.help{font-size:12px;color:rgba(255,255,255,.62)}
+.help--error{color:rgba(255,140,140,.95)}
+.help--success{color:rgba(155,255,190,.92)}
+
+.toggle{
+  display:inline-flex;
+  gap:6px;
+  padding:6px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.14);
+  background:rgba(255,255,255,.04);
+}
+.toggle button{
+  border:1px solid transparent;
+  background:transparent;
+  color:rgba(255,255,255,.72);
+  border-radius:999px;
+  padding:10px 14px;
+  cursor:pointer;
+  font-weight:700;
+  transition:background 160ms ease, color 160ms ease, transform 120ms ease;
+}
+.toggle button[aria-pressed="true"]{background:rgba(230,57,70,.20);color:#fff}
+.toggle button:hover{background:rgba(255,255,255,.06)}
+.toggle button:active{transform:scale(.98)}
+
+.table{
+  width:100%;
+  border-collapse:separate;
+  border-spacing:0;
+  overflow:hidden;
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+}
+.table th,.table td{padding:14px 14px;border-bottom:1px solid rgba(255,255,255,.10);text-align:left}
+.table th{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.70);background:rgba(0,0,0,.25)}
+.table tr:last-child td{border-bottom:none}
+.table td{color:rgba(255,255,255,.82)}
+.table td strong{color:#fff}
+.table-wrap{overflow:auto;border-radius:var(--radius)}
+
+.filters{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
+.select{
+  background:rgba(255,255,255,.04);
+  border:1px solid rgba(255,255,255,.14);
+  color:#fff;
+  padding:12px 14px;
+  border-radius:14px;
+  outline:none;
+}
+.grid{
+  display:grid;
+  grid-template-columns:repeat(4,1fr);
+  gap:16px;
+}
+.instructor{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.03));
+  overflow:hidden;
+  transition:transform 180ms ease, border-color 180ms ease;
+}
+.instructor:hover{transform:translateY(-2px);border-color:rgba(230,57,70,.36)}
+.instructor__img{height:180px;position:relative;overflow:hidden}
+.instructor__img img{width:100%;height:100%;object-fit:cover;filter:saturate(1.05) contrast(1.02)}
+.instructor__img::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg, rgba(0,0,0,.05), rgba(0,0,0,.60))}
+.instructor__body{padding:16px}
+.pill{display:inline-flex;align-items:center;gap:8px;border-radius:999px;padding:8px 10px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.04);font-size:12px;color:rgba(255,255,255,.72)}
+
+.accordion{display:grid;gap:10px}
+.acc-item{border-radius:var(--radius);border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.03);overflow:hidden}
+.acc-btn{
+  width:100%;
+  display:flex;align-items:center;justify-content:space-between;gap:14px;
+  padding:16px 16px;
+  border:none;
+  background:transparent;
+  color:#fff;
+  cursor:pointer;
+  text-align:left;
+}
+.acc-btn span{font-weight:750}
+.acc-btn svg{width:18px;height:18px;transition:transform 160ms ease}
+.acc-item[aria-expanded="true"] .acc-btn svg{transform:rotate(180deg)}
+.acc-panel{padding:0 16px 16px;color:rgba(255,255,255,.74)}
+.acc-panel[hidden]{display:none}
+
+.footer{border-top:1px solid rgba(255,255,255,.10);background:rgba(0,0,0,.22)}
+.footer__grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:18px;padding:42px 0}
+.footer h4{font-family:var(--font-display);letter-spacing:.08em;text-transform:uppercase;margin:0 0 10px}
+.footer a{color:rgba(255,255,255,.70);font-size:13px;display:block;padding:6px 0}
+.footer a:hover{color:#fff}
+.footer__bottom{border-top:1px solid rgba(255,255,255,.10);padding:14px 0;color:rgba(255,255,255,.60);font-size:13px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
+
+.country{position:relative;display:inline-flex;align-items:center;gap:10px}
+.country__btn{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:10px 12px;color:#fff;cursor:pointer}
+.country__menu{
+  position:absolute;right:0;bottom:calc(100% + 10px);
+  border:1px solid rgba(255,255,255,.14);
+  background:rgba(12,12,14,.96);
+  backdrop-filter:blur(12px);
+  border-radius:16px;
+  padding:8px;
+  min-width:180px;
+  box-shadow:var(--shadow);
+}
+.country__menu[hidden]{display:none}
+.country__menu button{width:100%;text-align:left;background:transparent;border:none;color:rgba(255,255,255,.80);padding:10px 10px;border-radius:12px;cursor:pointer}
+.country__menu button:hover{background:rgba(255,255,255,.06);color:#fff}
+
+.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
+
+@media (max-width: 980px){
+  .hero__grid{grid-template-columns:1fr;}
+  .hero__media{min-height:320px}
+  .grid{grid-template-columns:repeat(2,1fr)}
+  .footer__grid{grid-template-columns:1fr 1fr}
+}
+
+@media (max-width: 720px){
+  .h1{font-size:46px}
+  .h2{font-size:34px}
+  .nav{display:none}
+  .nav__utility{display:none}
+  .burger{display:inline-flex}
+  .grid-2{grid-template-columns:1fr}
+  .cta-band{flex-direction:column;align-items:flex-start}
+  .carousel__slide img{height:340px}
+  .form{grid-template-columns:1fr}
+  .grid{grid-template-columns:1fr}
+  .hero__panel-inner{padding:24px}
+}
*** End Patch
