python - <<'PY'
from pathlib import Path
import re
root=Path('output')
html=list(root.glob('*.html'))
print('pages', [p.name for p in html])
for p in html:
    t=p.read_text(encoding='utf-8')
    if 'assets/styles.css' not in t: print('missing css', p)
    if 'assets/app.js' not in t: print('missing js', p)
    # check nav/footer presence quickly
    if '<header class="header"' not in t: print('missing header', p)
    if '<footer class="footer"' not in t: print('missing footer', p)

# check required interaction hooks
checks={
 'home carousel':'index.html',
 'workout toggle':'the-workout.html',
 'instructors filter':'instructors.html',
 'faq accordion':'ride-faq.html',
}
content={p.name:p.read_text(encoding='utf-8') for p in html}
assert 'data-carousel' in content['index.html']
assert 'data-workout-toggle' in content['the-workout.html']
assert 'data-location-filter' in content['instructors.html']
assert 'data-accordion' in content['ride-faq.html']
print('hooks ok')

# check schedule items
sched=content['the-workout.html']
for needle in ['Tuesday','Full Body (Lower Focus)','Monday','Chest & Back','Thursday','Arms & Abs']:
    if needle not in sched:
        print('missing schedule needle', needle)
print('schedule ok')

# quick link check: internal hrefs should be relative
hrefs=[]
for p,t in content.items():
    hrefs += re.findall(r'href="([^"]+)"', t)
# collect site page links
for h in sorted(set([h for h in hrefs if h.endswith('.html')])):
    if not (root / h).exists():
        print('broken link', h)
print('link check done')
PY

